const input = $input.first().json;
const date = input.date || "";
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error("date must be YYYY-MM-DD; the Layer 1 sub-workflow refuses an unlabelled morning");
}
const model = input.model || "current";
if (!/^[a-z0-9_]+$/.test(model)) {
  throw new Error("model must be a lowercase adapter id");
}
const dataset = input.dataset || "data/usd-layer1-backtester/run-v1.json";
if (!/^[A-Za-z0-9._/-]+$/.test(dataset) || dataset.includes("..")) {
  throw new Error("dataset must be a repository-relative path");
}
const validation = input.validation || "structural";
if (validation !== "structural" && validation !== "receipted") {
  throw new Error("validation must be structural or receipted");
}
return [{ json: { date, model, dataset, validation } }];

const result = $input.first().json;
let payload;
try {
  payload = JSON.parse(result.stdout);
} catch (error) {
  throw new Error("the controller did not print JSON: " + error.message);
}
if (payload.error) {
  throw new Error("the controller refused the morning: " + payload.error);
}
const decision = Array.isArray(payload.decisions) ? payload.decisions[0] : null;
if (!decision) {
  throw new Error("the controller returned no decision for the requested date");
}
return [{
  json: Object.assign({}, decision, {
    controller_version: payload.controller_version,
    validation_mode: payload.validation_mode,
    dataset: payload.dataset,
    summary: payload.summary
  })
}];
